func:
// Aktuelle Werte aus dem Flow-Kontext lesen (0/false, falls noch nichts empfangen wurde)
var verbrauch = flow.get('verbrauch') || 0;
var einspeisung = flow.get('einspeisung') || 0;
var akku = flow.get('akku') || 0;
var boilerBoostOn = flow.get('boilerBoostOn') || false;
var aussenTemp = flow.get('aussenTemp'); // undefined, solange noch kein Wert vom Proxon-Fuehler da war

// Schwellwerte aus dem Flow-Kontext lesen (Defaults, falls Regler noch nicht bewegt wurden)
var akkuSchwelle = flow.get('akkuSchwelle');
if (akkuSchwelle === undefined) { akkuSchwelle = 90; }
var einspeisungSchwelle = flow.get('einspeisungSchwelle');
if (einspeisungSchwelle === undefined) { einspeisungSchwelle = 1200; }
var aussenTempSchwelle = flow.get('aussenTempSchwelle');
if (aussenTempSchwelle === undefined) { aussenTempSchwelle = 25; } // Default, bis der Regler bewegt wurde

// Ohne gueltigen Temperaturwert bleibt die Bedingung sicherheitshalber "nicht erfuellt"
var temperaturOk = (aussenTemp !== undefined) && (aussenTemp > aussenTempSchwelle);
var bedingungOk = temperaturOk && (akku >= akkuSchwelle) && (einspeisung > einspeisungSchwelle);
flow.set('acBedingungOk', bedingungOk); // fuer den Node "AC-Erinnerung pruefen"

// --- Hysterese ---
// Mindestlaufzeit, bevor wieder ausgeschaltet werden darf (schont den Kompressor)
var MIN_EIN_MS = 15 * 60 * 1000;
// Mindestpause, bevor wieder eingeschaltet werden darf
var MIN_AUS_MS = 10 * 60 * 1000;

var jetzt = Date.now();
var acState = flow.get('acState') || false;       // Soll-Zustand der Klimafunktion (von uns geschaltet)
var stateSeit = flow.get('acStateSeit') || 0;      // Zeitpunkt des letzten Zustandswechsels

var neuerState = acState;

if (!acState && bedingungOk) {
    // Einschalten nur erlaubt, wenn Mindestpause seit dem letzten Ausschalten vorbei ist
    if (stateSeit === 0 || (jetzt - stateSeit) >= MIN_AUS_MS) {
        neuerState = true;
    }
} else if (acState && !bedingungOk) {
    // Ausschalten nur erlaubt, wenn Mindestlaufzeit seit dem letzten Einschalten vorbei ist
    if ((jetzt - stateSeit) >= MIN_EIN_MS) {
        neuerState = false;
    }
}

if (neuerState !== acState) {
    flow.set('acState', neuerState);
    flow.set('acStateSeit', jetzt);

    var aussenTempText = (aussenTemp !== undefined) ? (aussenTemp + " °C (Min. " + aussenTempSchwelle + " °C)") : "unbekannt";
    var statusText = neuerState
        ? "Klimaanlage wird automatisch EINgeschaltet.\nAussentemperatur: " + aussenTempText + "\nAkku: " + akku + "% (Min. " + akkuSchwelle + "%)\nEinspeisung: " + einspeisung + " W (Min. " + einspeisungSchwelle + " W)"
        : "Klimaanlage wird automatisch AUSgeschaltet.\nAussentemperatur: " + aussenTempText + "\nAkku: " + akku + "% / Einspeisung: " + einspeisung + " W";

    // Ausgang 1: Betriebsart schreiben (Unit 41, Holding-Register 16) - 0=Aus, 1=Sommerbetrieb
    var msgBetriebsart = { payload: [ neuerState ? 1 : 0 ] };

    // Ausgang 2: Kuehlung freigeben (Unit 41, Holding-Register 62) - 0=AUS, 1=AN
    var msgKuehlung = { payload: [ neuerState ? 1 : 0 ] };

    // Ausgang 3: Pushover-Benachrichtigung ueber die Schaltung
    var msgPush = { payload: statusText, title: "Klimaanlage " + (neuerState ? "eingeschaltet" : "ausgeschaltet") };

    node.status({ fill: neuerState ? "green" : "grey", shape: "dot", text: neuerState ? "AN geschaltet" : "AUS geschaltet" });
    return [msgBetriebsart, msgKuehlung, msgPush];
} else {
    var statusLabel = acState ? "AN (Hysterese aktiv)" : "AUS (Hysterese aktiv)";
    if (!temperaturOk) { statusLabel += aussenTemp === undefined ? " - Temp. unbekannt" : " - zu kalt"; }
    node.status({ fill: acState ? "green" : "grey", shape: "ring", text: statusLabel });
    return [null, null, null];
}

// Aktuelle Werte aus dem Flow-Kontext (werden schon von den bestehenden MQTT-Nodes gepflegt)
var akku = flow.get('akku') || 0;
var einspeisung = flow.get('einspeisung') || 0;

// Schwellwerte (Regler), mit den bisherigen Shelly-Flow-Defaults als Fallback
var akkuSchwelle = flow.get('boilerAkkuSchwelle');
if (akkuSchwelle === undefined) { akkuSchwelle = 50; }
var solarSchwelle = flow.get('boilerSolarSchwelle');
if (solarSchwelle === undefined) { solarSchwelle = 800; }

var bedingungOk = (akku >= akkuSchwelle) && (einspeisung >= solarSchwelle);

// --- Hysterese ---
var MIN_EIN_MS = 10 * 60 * 1000;  // mind. 10 Min. an bleiben
var MIN_AUS_MS = 10 * 60 * 1000;  // mind. 10 Min. aus bleiben, bevor wieder eingeschaltet wird

var jetzt = Date.now();
var boostState = flow.get('boilerBoostState') || false;
var stateSeit = flow.get('boilerBoostStateSeit') || 0;

var neuerState = boostState;

if (!boostState && bedingungOk) {
    if (stateSeit === 0 || (jetzt - stateSeit) >= MIN_AUS_MS) {
        neuerState = true;
    }
} else if (boostState && !bedingungOk) {
    if ((jetzt - stateSeit) >= MIN_EIN_MS) {
        neuerState = false;
    }
}

if (neuerState !== boostState) {
    flow.set('boilerBoostState', neuerState);
    flow.set('boilerBoostStateSeit', jetzt);

    var statusText = neuerState
        ? "Boiler-Boost wird automatisch EINgeschaltet.\nAkku: " + akku + "% (Min. " + akkuSchwelle + "%)\nEinspeisung: " + einspeisung + " W (Min. " + solarSchwelle + " W)"
        : "Boiler-Boost wird automatisch AUSgeschaltet.\nAkku: " + akku + "% / Einspeisung: " + einspeisung + " W";

    // Ausgang 1: Shelly per MQTT schalten (gleiches Topic wie bisher, retained)
    var msgShelly = { topic: "Haus/Keller/Shelly/PVBoiler/command/switch:0", payload: neuerState ? "on" : "off" };

    // Ausgang 2: Pushover-Meldung
    var msgPush = { payload: statusText, title: "Boiler-Boost " + (neuerState ? "eingeschaltet" : "ausgeschaltet") };

    node.status({ fill: neuerState ? "green" : "grey", shape: "dot", text: neuerState ? "AN geschaltet" : "AUS geschaltet" });
    return [msgShelly, msgPush];
} else {
    node.status({ fill: boostState ? "green" : "grey", shape: "ring", text: boostState ? "AN (Hysterese aktiv)" : "AUS (Hysterese aktiv)" });
    return [null, null];
}

// Letzten bekannten Zustand behalten, damit ein Update von nur einem Register
// die anderen Anzeigewerte nicht auf "unbekannt" zuruecksetzt
var wpBetriebsart = context.get('wpBetriebsart');
var klimaZustand = context.get('klimaZustand');
var aussenTemp = context.get('aussenTemp');

if (msg.payload && msg.payload['u41_holding_16']) {
    // Betriebsart roh durchreichen: 0=Aus, 1=Sommerbetrieb, 2=Winterbetrieb, 3=ECO
    wpBetriebsart = msg.payload['u41_holding_16'].value;
    context.set('wpBetriebsart', wpBetriebsart);
}
if (msg.payload && msg.payload['u41_holding_62']) {
    // Kuehlung freigabe: 0 = AUS, 1 = AN
    klimaZustand = msg.payload['u41_holding_62'].value === 1 ? 1 : 0;
    context.set('klimaZustand', klimaZustand);
}
if (msg.payload && msg.payload['u41_input_198']) {
    // T3 Frischluft (Unit 41) = angesaugte Aussenluft vor dem Waermetauscher = Aussentemperatur-Sensor
    // (T9 auf Unit 20/T300 ist laut Proxon-Handbuch nur ein unbenutzter Reservefuehler "Extra", nicht die Aussenluft!)
    aussenTemp = msg.payload['u41_input_198'].value;
    context.set('aussenTemp', aussenTemp);
}

if (wpBetriebsart === undefined && klimaZustand === undefined && aussenTemp === undefined) {
    return null; // noch keines der Register je gelesen
}

return { payload: { wpBetriebsart: wpBetriebsart, klima: klimaZustand, aussenTemp: aussenTemp } };

const topics = ["akkuSchwelle", "einspeisungSchwelle", "verbrauchSchwelle", "aussenTempSchwelle", "boilerAkkuSchwelle", "boilerSolarSchwelle"];
const out = topics.map(t => {
    const v = global.get('schwellenwerte.' + t);
    return (v === undefined) ? null : { topic: t, payload: v };
});
return out;

// AC-Erkennung + Erinnerung
// Laeuft die Klimaanlage (Hausverbrauch > Verbrauch-Schwelle), obwohl die PV-Bedingung
// nicht (mehr) erfuellt ist, wird periodisch eine Pushover-Erinnerung ausgeloest.
// Typische Faelle: Anlage wurde von Hand eingeschaltet, oder das automatische
// Ausschalten per Modbus hat nicht funktioniert.
// Aufruf: bei jedem neuen Verbrauchswert und bei Aenderung der Verbrauch-Schwelle.

var verbrauch = flow.get('verbrauch') || 0;
var verbrauchSchwelle = flow.get('verbrauchSchwelle');
if (verbrauchSchwelle === undefined) { verbrauchSchwelle = 1000; } // Default, bis der Regler bewegt wurde

// Wird vom Node "AC-Bedingung pruefen & schalten (Hysterese)" bei jedem Durchlauf gesetzt
var bedingungOk = flow.get('acBedingungOk');
if (bedingungOk === undefined) {
    node.status({ fill: "grey", shape: "ring", text: "warte auf PV-Bedingung" });
    return null;
}

var acState = flow.get('acState') || false;
var acStateSeit = flow.get('acStateSeit') || 0;

// --- Zeiten ---
var VERZOEGERUNG_MS = 5 * 60 * 1000;   // so lange muss der Zustand anstehen (filtert Herd, Waschmaschine & Co.)
var ERINNERUNG_MS   = 30 * 60 * 1000;  // Abstand zwischen zwei Erinnerungen
var MIN_EIN_MS      = 15 * 60 * 1000;  // wie im Schalt-Node: waehrend der Mindestlaufzeit keine Erinnerung

var jetzt = Date.now();
var acLaeuft = verbrauch > verbrauchSchwelle;
var inMindestlaufzeit = acState && (jetzt - acStateSeit) < MIN_EIN_MS;
var problem = acLaeuft && !bedingungOk && !inMindestlaufzeit;

if (!problem) {
    // Alles in Ordnung -> Zaehler zuruecksetzen
    context.set('problemSeit', 0);
    context.set('letzteErinnerung', 0);
    var txt = acLaeuft ? "AC läuft" : "AC aus";
    if (inMindestlaufzeit && !bedingungOk) { txt += " (Mindestlaufzeit)"; }
    node.status({ fill: acLaeuft ? "green" : "grey", shape: "dot", text: txt + " – " + verbrauch + " W" });
    return null;
}

var problemSeit = context.get('problemSeit') || 0;
if (problemSeit === 0) {
    problemSeit = jetzt;
    context.set('problemSeit', problemSeit);
}
var dauerMin = Math.round((jetzt - problemSeit) / 60000);

if ((jetzt - problemSeit) < VERZOEGERUNG_MS) {
    node.status({ fill: "yellow", shape: "ring", text: "Verdacht seit " + dauerMin + " Min. (" + verbrauch + " W)" });
    return null;
}

var letzteErinnerung = context.get('letzteErinnerung') || 0;
if (letzteErinnerung !== 0 && (jetzt - letzteErinnerung) < ERINNERUNG_MS) {
    node.status({ fill: "red", shape: "ring", text: "läuft ohne PV seit " + dauerMin + " Min." });
    return null;
}
context.set('letzteErinnerung', jetzt);

// Werte fuer den Meldungstext (gleiche Defaults wie im Schalt-Node)
var akku = flow.get('akku') || 0;
var einspeisung = flow.get('einspeisung') || 0;
var aussenTemp = flow.get('aussenTemp');
var akkuSchwelle = flow.get('akkuSchwelle');
if (akkuSchwelle === undefined) { akkuSchwelle = 90; }
var einspeisungSchwelle = flow.get('einspeisungSchwelle');
if (einspeisungSchwelle === undefined) { einspeisungSchwelle = 1200; }
var aussenTempSchwelle = flow.get('aussenTempSchwelle');
if (aussenTempSchwelle === undefined) { aussenTempSchwelle = 25; }
var aussenTempText = (aussenTemp !== undefined) ? (aussenTemp + " °C (Min. " + aussenTempSchwelle + " °C)") : "unbekannt";

var statusText = "Die Klimaanlage läuft seit " + dauerMin + " Min., obwohl die PV-Bedingung nicht erfüllt ist." +
    "\nHausverbrauch: " + verbrauch + " W (Erkennung ab " + verbrauchSchwelle + " W)" +
    "\nAussentemperatur: " + aussenTempText +
    "\nAkku: " + akku + "% (Min. " + akkuSchwelle + "%)" +
    "\nEinspeisung: " + einspeisung + " W (Min. " + einspeisungSchwelle + " W)" +
    "\nNächste Erinnerung in " + Math.round(ERINNERUNG_MS / 60000) + " Min.";

node.status({ fill: "red", shape: "dot", text: "Erinnerung gesendet (" + dauerMin + " Min.)" });
return { payload: statusText, title: "Erinnerung: Klimaanlage läuft ohne PV-Überschuss", priority: 0 };
